                    "negItems",
                    "negCoding",
                    "corr",
                    "naData",
                    "model",
                    "algorithm",
                    "uniMethod",
                    "group",
                    "pairedVars",
                    "groupSeed",
                    "reportLang",
                    "nctIter",
                    "nctCorr",
                    "nctEdges",
                    "nctCentrality",
                    "nctAdjust"),
                columns=list(
                    list(
                        `name`="pair", 
                        `title`="Comparison", 
                        `type`="text"),
                    list(
                        `name`="item", 
                        `title`="Item", 
                        `type`="text"),
                    list(
                        `name`="measure", 
                        `title`="Measure", 
                        `type`="text"),
                    list(
                        `name`="diff", 
                        `title`="Difference", 
                        `type`="number", 
                        `format`="zto"),
                    list(
                        `name`="p", 
                        `title`="p (adjusted)", 
                        `type`="number", 
                        `format`="zto,pvalue"))))
            self$add(jmvcore::Html$new(
                options=options,
                name="nctInterpretation",
                title="Network Comparison Test interpretation",
                visible="(runNCT)"))
            self$add(jmvcore::Output$new(
                options=options,
                name="splitOV",
                title="Subsample",
                initInRun=TRUE,
                measureType="nominal",
                clearWith=list(
                    "vars",
                    "negItems",
                    "negCoding",
                    "corr",
                    "naData",
                    "model",
                    "algorithm",
                    "uniMethod",
                    "splitProp",
                    "splitSeed")))
            self$add(jmvcore::Html$new(
                options=options,
                name="notes",
                title="Notes"))}))

egaBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "egaBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "EGAnetLab",
                name = "ega",
                version = c(0,1,0),
                options = options,
                results = egaResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'none')
        }))

#' Exploratory Graph Analysis
#'
#' Estimates the number of dimensions underlying a set of items, and which 
