#' @param theoryFactors .
#' @param compareCFA .
#' @param negItems .
#' @param negCoding .
#' @param runHier .
#' @param runRI .
#' @param runCFA .
#' @param cfaEstimator .
#' @param splitSample .
#' @param splitProp .
#' @param splitSeed .
#' @param group .
#' @param pairedVars .
#' @param runInvariance .
#' @param invStructure .
#' @param invConfigCut .
#' @param invIter .
#' @param runNCT .
#' @param nctIter .
#' @param nctEdges .
#' @param nctCentrality .
#' @param nctCorr .
#' @param nctAdjust .
#' @param groupSeed .
#' @param showInvPlot .
#' @param runCentrality .
#' @param cenStandardize .
#' @param cenClosBetw .
#' @param showCenPlot .
#' @param runBootnet .
#' @param bnIter .
#' @param bnCaseIter .
#' @param bnSeed .
#' @param showEdgeCIPlot .
#' @param showCasePlot .
#' @param showKeySummary .
#' @param showChoicesGuide .
#' @param showLoadings .
#' @param showEdgeTable .
#' @param showNetworkPlot .
#' @param plotPalette .
#' @param layout .
#' @param plotTitle .
#' @param nodeSize .
#' @param nodeShape .
#' @param nodeAlpha .
#' @param labelSize .
#' @param labelColor .
#' @param edgeSize .
#' @param edgePosColor .
#' @param edgeNegColor .
#' @param edgeNegLty .
#' @param edgeMin .
#' @param showEdgeLabels .
#' @param edgeLabelSize .
#' @param edgeLabelDigits .
#' @param showLegend .
#' @param legendPosition .
#' @param legendTitle .
#' @param hierPlotTitle .
#' @param hierShowLevels .
#' @param hierItemLabels .
#' @param hierItemLabelSize .
#' @param hierItemSize .
#' @param hierDimSize .
#' @param hierEdgeWidth .
#' @param hierEdgeColor .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$intro} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$keySummary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$choicesGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summaryGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$membership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$loadingsGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$loadings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$interpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$edgeTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$networkPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$scoresGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$scores} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$netScoresOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$meanScoresOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$compareStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$compareTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$compareMembership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$compareInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$hierStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$hierSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$hierMembership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$hierPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$hierInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$riStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$riSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$riMembership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$riInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$uvaStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$uvaPairs} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$uvaSets} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$uvaInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootSummaryGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootSummary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bootFrequency} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bootDimStability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bootItemStability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bootInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bootItemPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$bootFrequencyPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$cfaStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cfaCompare} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cfaMembership} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cfaLoadings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cfaInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cfaHierModels} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cfaBifactorGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cfaBifactorLoadings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cfaBifactorInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cfaHierInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cenStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$cenTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cenPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$cenInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bnStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$bnCS} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bnEdges} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bnEdgePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$bnCasePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$bnInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$groupStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$groupSizes} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$invStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$invTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$invPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$invInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$nctStatus} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$nctGlobal} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$nctEdgeTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$nctCentralityTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$nctInterpretation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$splitOV} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
ega <- function(
    data,
    vars,
    reportLang = "en",
    corr = "auto",
    naData = "pairwise",
    model = "glasso",
    algorithm = "walktrap",
    uniMethod = "louvain",
    runBoot = FALSE,
    bootType = "parametric",
    iter = 500,
    seed = 2026,
    stabilityCut = 0.7,
    showItemPlot = TRUE,
    showFrequencyPlot = TRUE,
    runUVA = FALSE,
    uvaCut = 0.25,
    netScores = FALSE,
    runCompare = FALSE,
    compareAlgorithms = TRUE,
    theoryFactors = list(
                list(label="Factor 1", vars=list())),
    compareCFA = FALSE,
    negItems = list(),
    negCoding = "recoded",
    runHier = FALSE,
    runRI = FALSE,
    runCFA = FALSE,
    cfaEstimator = "auto",
    splitSample = FALSE,
    splitProp = 0.5,
    splitSeed = 2026,
    group = NULL,
    pairedVars = list(),
    runInvariance = FALSE,
    invStructure = "ega",
    invConfigCut = 0.7,
    invIter = 500,
    runNCT = FALSE,
    nctIter = 1000,
    nctEdges = FALSE,
    nctCentrality = FALSE,
    nctCorr = "pearson",
    nctAdjust = "holm",
    groupSeed = 2026,
    showInvPlot = TRUE,
    runCentrality = FALSE,
    cenStandardize = TRUE,
    cenClosBetw = FALSE,
    showCenPlot = TRUE,
    runBootnet = FALSE,
    bnIter = 1000,
    bnCaseIter = 1000,
    bnSeed = 2026,
    showEdgeCIPlot = TRUE,
    showCasePlot = TRUE,
    showKeySummary = TRUE,
    showChoicesGuide = TRUE,
    showLoadings = TRUE,
    showEdgeTable = FALSE,
    showNetworkPlot = TRUE,
    plotPalette = "default",
    layout = "qgraph",
    plotTitle = "",
    nodeSize = 12,
    nodeShape = "circle",
    nodeAlpha = 0.5,
    labelSize = 5,
    labelColor = "black",
    edgeSize = 8,
    edgePosColor = "darkgreen",
    edgeNegColor = "red",
    edgeNegLty = "solid",
    edgeMin = 0,
    showEdgeLabels = FALSE,
    edgeLabelSize = 3,
    edgeLabelDigits = 2,
    showLegend = TRUE,
    legendPosition = "right",
    legendTitle = "",
    hierPlotTitle = "",
    hierShowLevels = TRUE,
    hierItemLabels = TRUE,
    hierItemLabelSize = 3.3,
    hierItemSize = 4,
    hierDimSize = 11,
    hierEdgeWidth = 1,
    hierEdgeColor = "grey55") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ega requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(negItems)) negItems <- jmvcore::resolveQuo(jmvcore::enquo(negItems))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(pairedVars)) pairedVars <- jmvcore::resolveQuo(jmvcore::enquo(pairedVars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(negItems), negItems, NULL),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(pairedVars), pairedVars, NULL))

    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- egaOptions$new(
        vars = vars,
        reportLang = reportLang,
        corr = corr,
        naData = naData,
        model = model,
        algorithm = algorithm,
        uniMethod = uniMethod,
        runBoot = runBoot,
        bootType = bootType,
        iter = iter,
        seed = seed,
        stabilityCut = stabilityCut,
        showItemPlot = showItemPlot,
        showFrequencyPlot = showFrequencyPlot,
        runUVA = runUVA,
        uvaCut = uvaCut,
        netScores = netScores,
        runCompare = runCompare,
        compareAlgorithms = compareAlgorithms,
        theoryFactors = theoryFactors,
        compareCFA = compareCFA,
        negItems = negItems,
        negCoding = negCoding,
        runHier = runHier,
        runRI = runRI,
        runCFA = runCFA,
        cfaEstimator = cfaEstimator,
        splitSample = splitSample,
        splitProp = splitProp,
        splitSeed = splitSeed,
        group = group,
        pairedVars = pairedVars,
        runInvariance = runInvariance,
        invStructure = invStructure,
        invConfigCut = invConfigCut,
        invIter = invIter,
        runNCT = runNCT,
        nctIter = nctIter,
        nctEdges = nctEdges,
        nctCentrality = nctCentrality,
        nctCorr = nctCorr,
        nctAdjust = nctAdjust,
        groupSeed = groupSeed,
        showInvPlot = showInvPlot,
        runCentrality = runCentrality,
        cenStandardize = cenStandardize,
        cenClosBetw = cenClosBetw,
        showCenPlot = showCenPlot,
        runBootnet = runBootnet,
        bnIter = bnIter,
        bnCaseIter = bnCaseIter,
        bnSeed = bnSeed,
        showEdgeCIPlot = showEdgeCIPlot,
        showCasePlot = showCasePlot,
        showKeySummary = showKeySummary,
        showChoicesGuide = showChoicesGuide,
        showLoadings = showLoadings,
        showEdgeTable = showEdgeTable,
        showNetworkPlot = showNetworkPlot,
        plotPalette = plotPalette,
        layout = layout,
        plotTitle = plotTitle,
        nodeSize = nodeSize,
        nodeShape = nodeShape,
        nodeAlpha = nodeAlpha,
        labelSize = labelSize,
        labelColor = labelColor,
        edgeSize = edgeSize,
        edgePosColor = edgePosColor,
        edgeNegColor = edgeNegColor,
        edgeNegLty = edgeNegLty,
        edgeMin = edgeMin,
        showEdgeLabels = showEdgeLabels,
        edgeLabelSize = edgeLabelSize,
        edgeLabelDigits = edgeLabelDigits,
        showLegend = showLegend,
        legendPosition = legendPosition,
        legendTitle = legendTitle,
        hierPlotTitle = hierPlotTitle,
        hierShowLevels = hierShowLevels,
        hierItemLabels = hierItemLabels,
        hierItemLabelSize = hierItemLabelSize,
        hierItemSize = hierItemSize,
        hierDimSize = hierDimSize,
        hierEdgeWidth = hierEdgeWidth,
        hierEdgeColor = hierEdgeColor)

    analysis <- egaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

